// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        // owner is initially address(0); any caller must differ from the current owner
        vm.assume(actor != c.owner());
        address before = c.owner();
        vm.prank(actor);
        bool ok;
        try c.transferOwnership(actor) { ok = true; } catch { ok = false; }
        assertTrue(!ok && c.owner() == before);
    }
}
